import os,json,stat,subprocess
from pathlib import Path
src=Path("/var/www/fadego-preview");dst=Path("/srv/projects/fadego/www/preview")
project=Path("/srv/projects/fadego")
r={"phase":"fadego-web-preflight"}
for key,p in (("src",src),("project",project),("dst",dst),("www_parent",dst.parent)):
 r[key]={"exists":p.exists(),"link":p.is_symlink()}
 if p.exists():
  s=p.stat();r[key].update({"mode":oct(s.st_mode & 0o777),"uid":s.st_uid,"gid":s.st_gid,"dev":s.st_dev,"inode":s.st_ino})
  if p.is_dir():r[key]["entries"]=[x.name for x in p.iterdir()][:12]
def run(args):
 try:q=subprocess.run(args,capture_output=True,text=True,timeout=8);return {"code":q.returncode}
 except Exception as e:return {"error":type(e).__name__}
r["nginx_config"]=run(["nginx","-t"])
r["www_read_old"]=run(["runuser","-u","www-data","--","test","-r",str(src/"index.html")])
r["www_traverse_new_root"]=run(["runuser","-u","www-data","--","test","-x",str(project)])
r["nginx_symlinks_disabled"]=False
for base in ("/etc/nginx/nginx.conf","/etc/nginx/sites-available/fadego-staging.conf"):
 try:
  t=Path(base).read_text()
  if "disable_symlinks on" in t:r["nginx_symlinks_disabled"]=True
 except Exception:pass
print(json.dumps(r,sort_keys=True))
